"""Inert trusted5GiB VMM cap check; same-process FD positive only.
Root independently verifies actual Pod UID/parent cap and physical free>6GiB
before/during8sOOMhold. No cross-Pod or distinct-process denial claim.
"""
import argparse,base64,ctypes as C,hashlib,json,os,pathlib,sys,threading,time,types,uuid
SOURCE_B64=''
SOURCE_SHA256='9c533aa22d91a9c09febd77ee6fd515b4ce34107ff3b04f5a63fa777fea609cd'
MIB=1048576;STEP=64*MIB;CAP=5120*MIB

def emit(event,**data):
 print(json.dumps(dict(event=event,time_ns=time.time_ns(),monotonic_ns=time.monotonic_ns(),namespace_pid=os.getpid(),**data)),flush=True)

class TypedVmmOOM(Exception):pass

def touch(native,value,byte):
 native.lib.cuMemsetD8_v2.argtypes=[C.c_uint64,C.c_ubyte,C.c_size_t];native.lib.cuMemsetD8_v2.restype=C.c_int
 native.ok('cuMemsetD8_v2',value['address'],byte,STEP);native.ok('cuCtxSynchronize')
 last=C.c_ubyte();native.ok('cuMemcpyDtoH_v2',C.byref(last),value['address']+STEP-1,1)
 assert native.read(value['address'])==last.value==byte

def create_native(module):
 native=module.VmmNative();original=native.ok
 def checked(name,*args):
  if name=='cuMemCreate':
   result=native.lib.cuMemCreate(*args)
   if result==2:raise TypedVmmOOM('cuMemCreate returned CUDA_ERROR_OUT_OF_MEMORY')
   assert result==0,'cuMemCreate unexpected CUDA result '+str(result)
   return
  return original(name,*args)
 native.ok=checked
 return native

def main(argv=None):
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--execute',action='store_true')
 parser.add_argument('--pod-uid');parser.add_argument('--pod-name');parser.add_argument('--gpu-uuid')
 args=parser.parse_args(argv)
 if not args.execute:
  emit('inert',gpu_calls=False,api_calls=False,cap_bytes=CAP,step_bytes=STEP,max_attempts=81,
       source_sha256=SOURCE_SHA256,cross_pod_qualified=False,production_qualified=False);return 0
 assert args.pod_uid and str(uuid.UUID(args.pod_uid))==args.pod_uid
 assert args.pod_name and pathlib.Path('/etc/hostname').read_text().strip()==args.pod_name
 assert (os.getuid(),os.getgid())==(1000,100)
 assert not os.environ.get('LD_PRELOAD') and not os.environ.get('LD_AUDIT')
 preload=pathlib.Path('/etc/ld.so.preload');assert not preload.exists() or not preload.read_text().strip()
 assert os.environ.get('NVIDIA_VISIBLE_DEVICES')==args.gpu_uuid and os.environ.get('CUDA_VISIBLE_DEVICES')=='0'
 raw=base64.b64decode(SOURCE_B64,validate=True);assert hashlib.sha256(raw).hexdigest()==SOURCE_SHA256
 module=types.ModuleType('_trusted_vmm_cap');module.__file__='<pinned-vmm-native>';sys.modules[module.__name__]=module
 exec(compile(raw,module.__file__,'exec'),module.__dict__)
 assert args.gpu_uuid==module.GPU and module.CAP==CAP and module.BYTES==STEP
 watchdog=threading.Timer(80,lambda:os._exit(124));watchdog.daemon=True;watchdog.start()
 started=time.monotonic();native=None;failure=None;cleanup=[];oom=False;positive=False;held=0;recovery=False
 try:
  native=create_native(module)
  first=native.create();touch(native,first,37);held=STEP
  result,alias=native.import_fd(first['fd']);assert result==0 and alias is not None,'Same-parent FD import positive failed'
  native.map(alias);assert native.read(alias['address'])==37
  native.poke(alias['address'],41);assert native.read(first['address'])==41
  native.poke(first['address'],37);positive=True
  emit('same-process-same-parent-FD-positive',pod_uid=args.pod_uid,cgroup=pathlib.Path('/proc/self/cgroup').read_text().strip(),
       cuda_result=result,alias_readback=37,coherent_alias_write_readback=41,allocation_bytes=held)
  for step in range(2,82):
   if step*STEP>CAP:
    # Do not call create(): it maps/touches before returning. A successful
    # cap-exceeding raw physical allocation is freed without mapping/touch.
    prop=module.AllocationProp();prop.type=1;prop.requestedHandleTypes=1;prop.location=module.Location(1,0)
    handle=C.c_uint64();result=native.lib.cuMemCreate(C.byref(handle),STEP,C.byref(prop),0)
    if result==0:native.ok('cuMemRelease',handle.value)
    assert result==2,'VMM accepted physical allocation beyond5GiB; unexpected object never mapped/touched'
    oom=True;emit('typed-vmm-oom',api='cuMemCreate',cuda_result=2,attempt=step,allocated_bytes=held);break
   try:value=native.create()
   except TypedVmmOOM:
    oom=True;emit('typed-vmm-oom',api='cuMemCreate',cuda_result=2,attempt=step,allocated_bytes=held);break
   held+=STEP;assert held<=CAP;touch(native,value,37)
   emit('vmm-allocation-touched',step=step,allocated_bytes=held,first_and_last_readback=37)
  assert oom and 4096*MIB<=held<=CAP,'Meaningful near-cap VMM OOM (4..5GiB) required'
  emit('oom-held-start',pod_uid=args.pod_uid,allocated_bytes=held,hold_seconds=8,physical_free_gt6GiB_host_witness_required=True)
  time.sleep(8)
  assert native.read(first['address'])==37 and native.read(alias['address'])==37
  emit('oom-held-end',allocated_bytes=held,aliases_intact=True)
  native.close();cleanup.append('stress-context-all-maps-handles-FDs');native=None
  native=create_native(module);value=native.create();touch(native,value,53);recovery=True
  emit('recovery-kernel',allocated_bytes=STEP,first_and_last_readback=53)
 except BaseException as error:failure={'type':type(error).__name__,'detail':str(error)}
 finally:
  if native is not None:
   try:native.close();cleanup.append('final-context-all-maps-handles-FDs')
   except BaseException as error:failure={'type':type(error).__name__,'detail':'Explicit VMM cleanup failed: '+str(error)}
  watchdog.cancel()
 passed=failure is None and oom and positive and recovery and len(cleanup)==2
 emit('receipt',pod_uid=args.pod_uid,passed=passed,typed_oom2=oom,same_process_same_parent_FD_positive=positive,
      held_bytes=held,recovery=recovery,explicit_cleanup=cleanup,error=failure,seconds=time.monotonic()-started,
      independent_host_cap_and_physical_headroom_witness_required=True,cross_pod_qualified=False,
      distinct_process_import_qualified=False,managed_memory_qualified=False,production_qualified=False)
 return 0 if passed else 1

if __name__=='__main__':raise SystemExit(main())
